module "vpc" {
  source  = "./modules/vpc"
  version = "2.1.0"               # pinned: reproducible
  name    = "prod"
  cidr    = "10.0.0.0/16"
  azs     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}
output "vpc_id" { value = module.vpc.vpc_id }

# docker-compose mirroring prod topology (dev subset):
services:
  api: {build: ., ports: ["8080:8080"], env_file: .env.dev}
  db:  {image: postgres:16, volumes: [pgdata:/var/lib/postgresql/data]}
  cache: {image: redis:7}
# same service names, same env shape as prod manifests

Subnet discipline:
  public:  ALBs only (no workloads, ever)
  private: workloads (no public IPs; outbound via NAT)
  data:    databases (no internet route at all)
  Rules: workloads never in public; data never with internet route.
  Violations of this shape are the findings auditors live for.

{
  "Effect": "Allow",
  "Action": ["s3:GetObject"],
  "Resource": "arn:aws:s3:::app-artifacts/*",
  "Condition": {"StringEquals": {"aws:PrincipalTag/team": "api"}}
  // narrow action, narrow resource, ABAC condition: the shape of least privilege
}

apiVersion: argoproj.io/v1alpha1
kind: Application
metadata: {name: api-prod}
spec:
  project: default
  source: {repoURL: https://git/platform.git, path: apps/api/prod,
           targetRevision: v1.4.2}   # promotion = bump this ref
  destination: {server: https://prod-cluster, namespace: api}
  syncPolicy: {automated: {prune: true, selfHeal: true}}
